import{_ as o,a0 as l,w as r,s as d,ao as p,I as i,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"awk 系列：如何使用 awk 複合表達式 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 複合表達式 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 複合表達式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 複合表達式 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 5 - How to Use Compound Expressions with Awk in Linux","title":"awk 系列：如何使用 awk 複合表達式","tag":"awk","desc":""},"relativePath":"awk/Part 5 - How to Use Compound Expressions with Awk in Linux.md","filePath":"[post].md"}'),k={name:"awk/Part 5 - How to Use Compound Expressions with Awk in Linux.md"};function c(u,s,h,w,m,g){const t=l("Link");return r(),d("div",null,[s[16]||(s[16]=p('<h1 id="awk-系列-如何使用-awk-複合表達式" tabindex="-1">awk 系列：如何使用 awk 複合表達式 <a class="header-anchor" href="#awk-系列-如何使用-awk-複合表達式" aria-label="Permalink to “awk 系列：如何使用 awk 複合表達式”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Use-Compound-Expressions-with-Awk.png" alt=""></p><p>一直以來在查對條件是否匹配時，我們使用的都是簡單的表達式。那如果你想用超過一個表達式來查對特定的條件呢？</p><p>本文，我們將看看如何在過濾文本和字符串時，結合多個表達式，即複合表達式，用以查對條件。</p><p>awk 的複合表達式可由表示“與”的組合操作符 <code>&amp;&amp;</code> 和表示“或”的 <code>||</code> 構成。</p><p>複合表達式的常規寫法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>( 第一個表達式 ) &amp;&amp; ( 第二個表達式 )</span></span></code></pre></div><p>這裏只有當“第一個表達式” 和“第二個表達式”都是真值時整個表達式才為真。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>( 第一個表達式 ) || ( 第二個表達式)</span></span></code></pre></div><p>這裏只要“第一個表達式” 為真或“第二個表達式”為真，整個表達式就為真。</p><p><strong>注意</strong>：切記要加括號。</p>',11)),i("p",null,[s[1]||(s[1]=a("表達式可以由比較操作符構成，具體可查看",-1)),e(t,{href:"https://linux.cn/article-7602-1.html"},{default:n(()=>[...s[0]||(s[0]=[a(" awk 系列的第四節",-1)])]),_:1}),s[2]||(s[2]=a("。",-1))]),s[17]||(s[17]=p(`<p>現在讓我們通過一個例子來加深理解：</p><p>此例中，有一個文本文件 <code>tecmint_deals.txt</code>，文本中包含着一張隨機的 Tecmint 交易清單，其中包含了名稱、價格和種類。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TecMint Deal List</span></span>
<span class="line"><span>No      Name                                    Price           Type</span></span>
<span class="line"><span>1       Mac_OS_X_Cleanup_Suite                  $9.99           Software</span></span>
<span class="line"><span>2       Basics_Notebook                         $14.99          Lifestyle</span></span>
<span class="line"><span>3       Tactical_Pen                            $25.99          Lifestyle</span></span>
<span class="line"><span>4       Scapple                                 $19.00          Unknown</span></span>
<span class="line"><span>5       Nano_Tool_Pack                          $11.99          Unknown</span></span>
<span class="line"><span>6       Ditto_Bluetooth_Altering_Device         $33.00          Tech</span></span>
<span class="line"><span>7       Nano_Prowler_Mini_Drone                 $36.99          Tech</span></span></code></pre></div><p>我們只想打印出價格超過 $20 且其種類為 “Tech” 的物品，在其行末用 (*) 打上標記。</p><p>我們將要執行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;($3 ~ /^\\$[2-9][0-9]*\\.[0-9][0-9]$/) &amp;&amp; ($4==&quot;Tech&quot;) { printf &quot;%s\\t%s\\n&quot;,$0,&quot;*&quot;; } &#39; tecmint_deals.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>6	Ditto_Bluetooth_Altering_Device		$33.00		Tech	*</span></span>
<span class="line"><span>7	Nano_Prowler_Mini_Drone			$36.99          Tech	 *</span></span></code></pre></div><p>此例，在複合表達式中我們使用了兩個表達式：</p><ul><li>表達式 1：<code>($3 ~ /^\\$[2-9][0-9]*\\.[0-9][0-9]$/)</code> ；查找交易價格超過 <code>$20</code> 的行，即只有當 <code>$3</code> 也就是價格滿足 <code>/^\\$[2-9][0-9]*\\.[0-9][0-9]$/</code> 時值才為真值。</li><li>表達式 2：<code>($4 == “Tech”)</code> ；查找是否有種類為 “<code>Tech</code>”的交易，即只有當 <code>$4</code> 等於 “<code>Tech</code>” 時值才為真值。 切記，只有當 <code>&amp;&amp;</code> 操作符的兩端狀態，也就是兩個表達式都是真值的情況下，這一行才會被打上 <code>(*)</code> 標誌。</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>有些時候為了真正符合你的需求，就不得不用到複合表達式。當你掌握了比較和複合表達式操作符的用法之後，複雜的文本或字符串過濾條件也能輕鬆解決。</p><p>希望本嚮導對你有所幫助，如果你有任何問題或者補充，可以在下方發表評論，你的問題將會得到相應的解釋。</p><hr>`,12)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),e(t,{href:"http://www.tecmint.com/combine-multiple-expressions-in-awk/"},{default:n(()=>[...s[3]||(s[3]=[a("http://www.tecmint.com/combine-multiple-expressions-in-awk/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=a("作者：",-1)),e(t,{href:"http://www.tecmint.com/author/aaronkili/"},{default:n(()=>[...s[5]||(s[5]=[a("Aaron Kili",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),e(t,{href:"https://github.com/martin2011qi"},{default:n(()=>[...s[6]||(s[6]=[a("martin2011qi",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const b=o(k,[["render",c]]);export{f as __pageData,b as default};
